import {bookingPaceReport} from './revenue-pace-report';
import {pickupBatchSnapshots} from './revenue-pickup-report';
import {reportDecimal,reportMoney,type ReportCell} from './report-export';
export function paceExportRows(input:Parameters<typeof bookingPaceReport>[0],types:{id:string;name:string}[]):ReportCell[][]{
 const result=bookingPaceReport(input),a=pickupBatchSnapshots(input.reference,input.tenant,input.property,input.referenceCapture),b=pickupBatchSnapshots(input.current,input.tenant,input.property,input.currentCapture);
 const number=(value:number|null):ReportCell=>value===null?'Unavailable':reportDecimal(String(value));
 const rows:ReportCell[][]=[['Booking pace - development preview'],['Basis','Explicit paired stay dates at equal property-local lead day and clock second. Not a forecast.'],['Time zone',input.timeZone],['Reference capture',input.referenceCapture],['Current capture',input.currentCapture],['Tenant','Property','Reference night','Current night','Room type ID','Room type','Currency','Reference captured at','Current captured at','Status','Lead days','Booked-night difference','Room revenue difference','Capacity difference','Reference occupancy percent','Current occupancy percent','Occupancy change percentage points']];
 for(const row of result){const previous=a.find(s=>s.roomTypeId===row.roomTypeId&&s.stayDate===row.referenceDate),current=b.find(s=>s.roomTypeId===row.roomTypeId&&s.stayDate===row.currentDate),r=row.comparison;
 rows.push([row.tenant,row.property,row.referenceDate,row.currentDate,row.roomTypeId,types.find(t=>t.id===row.roomTypeId)?.name??'Unknown room type',(current??previous)?.currency??'Unavailable',previous?.capturedAt??'Unavailable',current?.capturedAt??'Unavailable',r.available?'Comparable':r.reason,r.available?r.leadDays:'Unavailable',r.available?number(r.roomNightsDifference):'Unavailable',r.available&&r.revenueDifferenceMinor!==null?reportDecimal(reportMoney(r.revenueDifferenceMinor)):'Unavailable',r.available?number(r.capacityDifference):'Unavailable',r.available&&r.previousOccupancy!==null?reportDecimal((r.previousOccupancy*100).toFixed(1)):'Unavailable',r.available&&r.currentOccupancy!==null?reportDecimal((r.currentOccupancy*100).toFixed(1)):'Unavailable',r.available&&r.occupancyPercentagePointDifference!==null?reportDecimal(r.occupancyPercentagePointDifference.toFixed(1)):'Unavailable']);}
 return rows;
}
